parameters.jsCode:
// Flatten the Error Trigger payload and guess at a classification.
//
// Two shapes arrive here and they are not the same. A workflow that failed
// while running sends `execution`; a trigger that could not even start sends
// `trigger`. Reading only `execution` means the second kind silently writes
// nulls -- which is exactly the failure you least want to lose, because a
// trigger that stopped firing produces no executions at all and therefore no
// other signal.
const d = $json;
const e = d.execution ?? d.trigger ?? {};
const wf = d.workflow ?? {};

const message = e.error?.message ?? e.error?.description ?? 'unknown error';
const node = e.lastNodeExecuted ?? e.error?.node?.name ?? 'unknown';

// Classifying by matching the error text is the weakest part of this whole
// repository, and it is deliberate that it lives HERE rather than in the
// pipeline. Inside a workflow, failures are classified structurally: an
// error output is permanent, an exhausted retry is transient, and no string
// is parsed. By the time something reaches this node, all that structure is
// gone and a message is the only evidence left.
//
// So treat the label as a hint for triage and never as a decision anything
// automatic depends on. If a class of failure starts mattering, the fix is
// to catch it at its node, not to add a regex here.
const TRANSIENT = [
  /ECONNREFUSED/i, /ECONNRESET/i, /ETIMEDOUT/i, /ENOTFOUND/i,
  /socket hang up/i, /timeout/i, /\b429\b/, /\b5\d\d\b/,
  /too many connections/i, /deadlock/i,
];
const looksTransient = TRANSIENT.some((r) => r.test(message));

return [{ json: {
  workflow_id: wf.id ?? 'unknown',
  workflow_name: wf.name ?? 'unknown',
  execution_id: String(e.id ?? 'none'),
  execution_url: e.url ?? `${$env.N8N_EDITOR_BASE_URL}/workflow/${wf.id}/executions/${e.id}`,
  node,
  kind: 'crashed',
  error: message,
  // 'crashed' rather than 'exhausted' or 'permanent': nothing here was
  // retried by a policy, the execution simply stopped. Keeping it a distinct
  // reason is what makes 'how many of our failures are unhandled' a query.
  reason: 'crashed',
  looks_transient: looksTransient,
  retry_of: e.retryOf ?? null,
  mode: e.mode ?? null,
  payload: d,
} }];

parameters.jsonBody:
={{ JSON.stringify({ text: `${$('Classify').first().json.workflow_name} CRASHED at node '${$('Classify').first().json.node}'
${$('Classify').first().json.error}
looks transient: ${$('Classify').first().json.looks_transient}
${$('Classify').first().json.execution_url}` }) }}
